using ModelContextProtocol.Server;
using ModelContextProtocol.Protocol;
using System.Reflection;

// Dump public members of key types
var types = new[] {
    typeof(McpServerToolAttribute),
    typeof(McpServerPromptAttribute),
    typeof(McpServerToolTypeAttribute),
    typeof(McpServerPromptTypeAttribute),
};
foreach (var t in types)
{
    Console.WriteLine($"\n=== {t.Name} ===");
    foreach (var p in t.GetProperties()) Console.WriteLine($"  P: {p.Name} : {p.PropertyType.Name}");
    foreach (var c in t.GetConstructors()) Console.WriteLine($"  C: {string.Join(", ", c.GetParameters().Select(x => $"{x.ParameterType.Name} {x.Name}"))}");
}

// Check PromptMessage, GetPromptResult
var pt = typeof(PromptMessage);
Console.WriteLine($"\n=== {pt.Name} ===");
foreach (var p in pt.GetProperties()) Console.WriteLine($"  P: {p.Name} : {p.PropertyType.Name}");

var gpr = typeof(GetPromptResult);
Console.WriteLine($"\n=== {gpr.Name} ===");
foreach (var p in gpr.GetProperties()) Console.WriteLine($"  P: {p.Name} : {p.PropertyType.Name}");

// CallToolResult
var ctr = typeof(CallToolResult);
Console.WriteLine($"\n=== {ctr.Name} ===");
foreach (var p in ctr.GetProperties()) Console.WriteLine($"  P: {p.Name} : {p.PropertyType.Name}");

// Role enum
var role = typeof(Role);
Console.WriteLine($"\n=== {role.Name} ===");
foreach (var f in role.GetFields().Where(f => f.IsStatic)) Console.WriteLine($"  {f.Name}");

// Content
var content = typeof(Content);
Console.WriteLine($"\n=== {content.Name} ===");
foreach (var p in content.GetProperties()) Console.WriteLine($"  P: {p.Name} : {p.PropertyType.Name}");
foreach (var m in content.GetMethods(BindingFlags.Public | BindingFlags.Static)) Console.WriteLine($"  M: {m.Name}({string.Join(", ", m.GetParameters().Select(x => $"{x.ParameterType.Name} {x.Name}"))}) : {m.ReturnType.Name}");
CSHARP
