using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool(Name = "fetch_data"), Description("Fetches data from an external API by resource path.")]
    public async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        [Description("API resource path, e.g. /users/1")] string path,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("api");
        using var response = await client.GetAsync(path, cancellationToken);

        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

        return JsonSerializer.Serialize(doc.RootElement, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizePrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Generates a prompt to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional maximum length in sentences")] int? maxSentences = 3)
    {
        var constraint = maxSentences.HasValue
            ? $" Limit the summary to {maxSentences.Value} sentence(s)."
            : string.Empty;

        return new()
        {
            Description = "Summarize the provided text",
            Messages =
            [
                new()
                {
                    Role = Role.User,
                    Content = new TextContentBlock
                    {
                        Text = $"Please provide a concise summary of the following text.{constraint}\n\n{text}"
                    }
                }
            ]
        };
    }
}

